import assert from "node:assert/strict";
import { test } from "node:test";
import {
	BASE_CSS,
	COMPONENTS,
	HtmlError,
	analyzeDocument,
	componentsMarkdown,
	fillDocument,
	parseArgs,
	resolvePagePath,
	scratchDocument,
	snippetClasses
} from "../index.js";

/* ------------------------------------------------------------- catalogue */

test("the catalogue is a real kit: unique ids, every entry has a snippet", () => {
	assert.ok(COMPONENTS.length >= 12, `expected a usable kit, got ${COMPONENTS.length}`);
	const ids = new Set();
	for (const one of COMPONENTS) {
		assert.ok(one.id.length > 0 && !ids.has(one.id), `duplicate id ${one.id}`);
		ids.add(one.id);
		assert.ok(one.when.length > 0, `${one.id} needs a "when to use" line`);
		assert.ok(one.snippet.trim().length > 0, `${one.id} needs a snippet`);
	}
});

test("every class a snippet uses is defined by the shipped stylesheet", () => {
	const style = BASE_CSS.replace("__ACCENT__", "#000");
	const missing = snippetClasses().filter((cls) => !style.includes(`.${cls}`));
	assert.deepEqual(missing, [], `classes used by snippets but absent from BASE_CSS: ${missing.join(", ")}`);
});

test("the stylesheet itself is offline-safe and theme-aware", () => {
	assert.equal(/https?:\/\//.test(BASE_CSS), false, "BASE_CSS must not reference the network");
	assert.ok(BASE_CSS.includes("prefers-color-scheme"), "dark mode is part of the kit");
	assert.ok(BASE_CSS.includes("--accent"), "accent token must exist so create() can recolour a page");
});

test("the catalogue can be narrowed to the components a page needs", () => {
	const md = componentsMarkdown(["card", "steps"]);
	assert.ok(md.includes("## card"));
	assert.ok(md.includes("## steps"));
	assert.equal(md.includes("## table"), false);
	assert.ok(md.includes("```html"));
});

/* ---------------------------------------------------------------- template */

test("create writes a self-contained, mobile-first document", () => {
	const page = scratchDocument({ title: "训练计划", eyebrow: "8 周", content: "<p>hi</p>" });
	assert.ok(page.startsWith("<!doctype html>"));
	assert.ok(page.includes('name="viewport"'));
	assert.ok(page.includes("prefers-color-scheme"));
	assert.ok(page.includes("<!-- dsh:content -->"));
	assert.ok(page.includes("<!-- dsh:content:end -->"));
	assert.ok(page.includes("<!-- dsh:end -->"));
	assert.equal(/https?:\/\//.test(page), false, "a generated page must not need the network");
	assert.equal(/window\.print/.test(page), false, "the shell owns printing");
	assert.equal(/<script[^>]+src=/.test(page), false, "no external scripts");
});

test("an accent passed by the caller reaches the page, and unsafe titles are escaped", () => {
	const page = scratchDocument({ title: "<b>x</b>", accent: "#f2542d" });
	assert.ok(page.includes("--accent: #f2542d"));
	assert.ok(page.includes("&lt;b&gt;x&lt;/b&gt;"));
});

/* -------------------------------------------------------------------- fill */

test("fill replaces the content slot and keeps the skeleton", () => {
	const base = scratchDocument({ title: "t" });
	const filled = fillDocument(base, '<section class="card">A</section>', "replace");
	assert.ok(filled.includes('<section class="card">A</section>'));
	assert.ok(filled.includes("<!-- dsh:content -->"));
	assert.ok(filled.indexOf('<section class="card">A</section>') < filled.indexOf("<!-- dsh:content:end -->"));
	assert.ok(filled.indexOf('<section class="card">A</section>') < filled.indexOf("</main>"));
});

test("fill with append adds another section inside <main>, not after the footer", () => {
	let page = scratchDocument({ title: "t", content: "<p>one</p>" });
	page = fillDocument(page, "<p>two</p>", "append");
	assert.ok(page.includes("<p>one</p>"));
	assert.ok(page.includes("<p>two</p>"));
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("<!-- dsh:content:end -->"));
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("</main>"), "appended content must stay inside <main>");
	assert.ok(page.indexOf("<p>two</p>") < page.indexOf("<footer"), "appended content must come before the footer");
});

test("fill refuses a page that has no markers", () => {
	assert.throws(() => fillDocument("<html></html>", "<p>x</p>", "replace"), (error) => {
		return error instanceof HtmlError && error.code === "HTML_NO_MARKER";
	});
});

/* ------------------------------------------------------------------- paths */

test("page paths must stay inside the workspace", () => {
	assert.equal(resolvePagePath("/w", "plan.html").relative, "plan.html");
	assert.equal(resolvePagePath("/w", "sub/plan.htm").relative, "sub/plan.htm");
	for (const bad of ["/etc/x.html", "../x.html", "a/../../x.html"]) {
		assert.throws(() => resolvePagePath("/w", bad), (error) => error.code === "HTML_BAD_PATH", bad);
	}
});

test("only html files are pages", () => {
	for (const bad of ["a.md", "a.js", "noext"]) {
		assert.throws(() => resolvePagePath("/w", bad), (error) => error.code === "HTML_BAD_PATH", bad);
	}
});

/* ------------------------------------------------------------------ checks */

test("a page built from the kit passes check", () => {
	const page = scratchDocument({
		title: "t",
		content: '<div class="stats"><div class="stat"><div class="stat-value">5</div></div></div>'
	});
	const report = analyzeDocument(page, { path: "a.html" });
	assert.deepEqual(report.errors, []);
	assert.deepEqual(report.warnings, []);
	assert.equal(report.ok, true);
});

test("external references are errors, with the line number", () => {
	const page = scratchDocument({ title: "t", content: '<img src="https://example.com/a.png">' });
	const report = analyzeDocument(page, { path: "a.html" });
	assert.equal(report.ok, false);
	assert.ok(report.errors.some((one) => one.includes("远程媒体")));
	assert.ok(report.errors.some((one) => /第 \d+ 行/.test(one)));
});

test("a missing viewport is a hard error: desktop width on a phone", () => {
	const report = analyzeDocument("<html><body><h1>x</h1></body></html>", { path: "a.html" });
	assert.ok(report.errors.some((one) => one.includes("viewport")));
});

test("a print button is a warning, because the shell owns exporting", () => {
	const report = analyzeDocument(
		'<html><head><meta name="viewport" content="x"><style>:root{color-scheme:light dark}</style></head>' +
		'<body><h1>x</h1><button onclick="window.print()">打印</button></body></html>',
		{ path: "a.html" }
	);
	assert.ok(report.warnings.some((one) => one.includes("window.print")));
});

test("a second stylesheet and unknown classes are reported as drift", () => {
	const report = analyzeDocument(
		'<html><head><meta name="viewport" content="x"><style>a{}</style><style>.mine{}</style></head>' +
		'<body><h1>x</h1><div class="my-own-thing">y</div></body></html>',
		{ path: "a.html" }
	);
	assert.ok(report.warnings.some((one) => one.includes("<style>")));
	assert.ok(report.warnings.some((one) => one.includes("my-own-thing")));
});

test("the size ceiling is an error, not a silent trim", () => {
	const report = analyzeDocument(scratchDocument({ title: "t" }), { path: "a.html", maxKb: 0.1 });
	assert.ok(report.errors.some((one) => one.includes("超过上限")));
});

/* -------------------------------------------------------------------- args */

test("unknown actions and missing paths are refused with a code", () => {
	assert.throws(() => parseArgs({ action: "paint", path: "a.html" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "create", path: "a.html", accent: "red" }), (error) => error.code === "HTML_BAD_ARGS");
	assert.throws(() => parseArgs({ action: "fill", path: "a.html", mode: "sideways" }), (error) => error.code === "HTML_BAD_ARGS");
});

test("components does not need a path, and component filters are kept", () => {
	const parsed = parseArgs({ action: "components", components: ["card"] });
	assert.equal(parsed.action, "components");
	assert.deepEqual(parsed.components, ["card"]);
});
